"""Genera una versión narrativa y más natural del informe de Tarea 2."""
from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import cm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Image, Table, TableStyle, PageBreak
import pandas as pd

ROOT=Path(__file__).resolve().parents[1]
BASE=ROOT/'datos'/'punto2'/'Abtsgmuend_Untergroeningen'
PDF=ROOT/'output'/'pdf'/'informe_tarea2_humano.pdf'
pdfmetrics.registerFont(TTFont('Arial',r'C:\Windows\Fonts\arial.ttf'))
pdfmetrics.registerFont(TTFont('Arial-Bold',r'C:\Windows\Fonts\arialbd.ttf'))
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='Body',fontName='Arial',fontSize=9.4,leading=12.5,spaceAfter=5,alignment=4))
s.add(ParagraphStyle(name='H1',fontName='Arial-Bold',fontSize=14,leading=17,spaceBefore=8,spaceAfter=4,textColor=colors.HexColor('#17365D')))
s.add(ParagraphStyle(name='H2',fontName='Arial-Bold',fontSize=11.2,leading=14,spaceBefore=6,spaceAfter=3,textColor=colors.HexColor('#28527A')))
s.add(ParagraphStyle(name='TitleC',fontName='Arial-Bold',fontSize=18,leading=22,alignment=TA_CENTER,textColor=colors.HexColor('#17365D')))
P=lambda t,st='Body': Paragraph(t,s[st])
def I(path,w,h):
    return Image(str(path),width=w,height=h) if Path(path).exists() else P('<i>Figura pendiente de regeneración; el resultado numérico se conserva en las tablas y archivos de datos.</i>','Body')
def footer(c,d):
    c.saveState(); c.setFont('Arial',8); c.setFillColor(colors.HexColor('#666666')); c.drawString(2*cm,1.1*cm,'Tarea 2 de Hidrología | Informe de trabajo'); c.drawRightString(A4[0]-2*cm,1.1*cm,f'Página {d.page}'); c.restoreState()
def tbl(data):
    t=Table(data,colWidths=[2.3*cm]*len(data[0]),repeatRows=1); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#D9EAF7')),('FONTNAME',(0,0),(-1,0),'Arial-Bold'),('FONTNAME',(0,1),(-1,-1),'Arial'),('FONTSIZE',(0,0),(-1,-1),8),('GRID',(0,0),(-1,-1),.3,colors.HexColor('#9EADBA')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F6F9FB')]),('ALIGN',(1,1),(-1,-1),'RIGHT')]))
    return t

story=[Spacer(1,1.7*cm),Spacer(1,2.2*cm),P('UNIVERSIDAD NACIONAL DE COLOMBIA','TitleC'),Spacer(1,1.1*cm),P('Tarea 2 de Hidrología:<br/>Evapotranspiración y diseño hidrológico','TitleC'),Spacer(1,1.1*cm),P('<b>Andrés Francisco Idrobo Hidrobo — ID. 1089568711</b><br/>Facultad de Minas — Ingeniería Civil'),Spacer(1,.35*cm),P('<b>Enmaly Aleli Manturano Grajeda — ID. 125817023</b><br/>Facultad de Minas — Ingeniería Geológica'),Spacer(1,.35*cm),P('<b>Jeyson Cristian Javier Irpanoca — ID. 125496042</b><br/>Facultad de Minas — Ingeniería Geológica'),Spacer(1,1.0*cm),P('Asignatura: Hidrología<br/>Docente: Carlos David Hoyos<br/><br/>Fecha de entrega: 24 de noviembre de 2026'),PageBreak()]
story += [P('Resumen','H1'),P('Este informe explica, paso a paso, cómo se pasó de una serie de lluvia de 10 minutos a una propuesta preliminar de obras de drenaje. Primero se revisaron los datos; luego se estimaron las lluvias extremas y las curvas IDF; finalmente se probó el comportamiento de una alcantarilla y de un tanque de detención. Los resultados se presentan junto con sus incertidumbres y con las limitaciones que deben tenerse presentes al interpretarlos.')]
story += [P('1. Espacio reservado para el punto 1','H1'),P('<b>Esta sección queda reservada para que el grupo incorpore el análisis de evapotranspiración de la Tarea 1.</b> No se ha inventado contenido para ese punto. Aquí deberán insertarse la cuenca PE_200907/Racarumi, sus datos, metodología, resultados y conclusiones.')]
story += [P('2. Punto 2: análisis hidrológico','H1'),P('El punto 2 se trabajó con la estación DWD 00020, Abtsgmünd–Untergröningen, porque su resolución de 10 minutos permite estudiar tormentas cortas. La estrategia fue mantener separados los datos observados, los resultados calculados y las hipótesis de diseño.')]
story += [P('2.1 Datos y control de calidad','H2'),P('La revisión empezó conservando los archivos originales y leyendo fecha, precipitación y código de calidad. Los valores inválidos se marcaron como ausentes, sin inventar observaciones mediante interpolación. Después se comprobaron intervalos de tiempo, meses incompletos y años hidrológicos. Con el MDE SRTM se delimitó una microcuenca sintética de 0.123154 km², con cauce principal de 382.69 m y pendiente de 0.1254 m/m. La estación está fuera de la microcuenca, por lo que se utiliza como referencia regional de lluvia.'),I(BASE/'control_2_1'/'mapa_revision_visual.png',14.5*cm,10.4*cm)]
story += [P('2.2 Extremos y distribuciones','H2'),P('Con la serie depurada se calcularon máximos anuales para varias duraciones, desde 10 minutos hasta 24 horas. Se compararon Gumbel, GEV y Log-Pearson III usando momentos, L-momentos y máxima verosimilitud. Las pruebas KS y Cramér–von Mises, junto con los gráficos de probabilidad, favorecieron la GEV-MLE. La decisión es estadística: describe el mejor ajuste de la muestra, pero no elimina la incertidumbre física de extrapolar eventos raros.'),P('Para medir esa incertidumbre se aplicó bootstrap. Los intervalos se ensanchan para retornos altos y duraciones largas, especialmente entre 12 y 24 horas. Las pruebas de Kendall no detectaron tendencias significativas al 5 %; por eso se afirma que no se detectó una tendencia en la muestra, sin asegurar que el clima futuro sea estacionario.'),I(BASE/'extremos_2_2'/'graficas_probabilidad_2_2.png',12.8*cm,14.6*cm)]
story += [P('2.3 Curvas IDF','H2'),P('A partir de la GEV-MLE se construyeron las curvas IDF. La primera comprobación fue hidrológica: las intensidades deben disminuir cuando aumenta la duración y aumentar cuando aumenta el periodo de retorno. Luego se contrastaron con KOSTRA-DWD-2020. Para retornos altos la curva local es más severa; el cociente local/KOSTRA alcanza aproximadamente 2.03 para 1 hora y 2.08 para 6 horas con T=100 años. El máximo horario de 2021 fue 48.27 mm y corresponde a un periodo de retorno aproximado de 17.4 años; este dato no se interpreta por sí solo como cambio climático.'),I(BASE/'idf_2_3'/'idf_gev_mle.png',13.5*cm,8.2*cm)]
story += [P('2.4 Diseño de obras','H2'),P('El outlet se ubicó en 48.9181944° N y 9.9123611° E. Visualmente coincide con el extremo aguas abajo del cauce derivado del MDE y queda dentro del polígono. Las geometrías OSM no confirmaron que sea una obra real; por eso se reporta como outlet sintético y esta limitación acompaña todos los resultados hidráulicos.'),P('Para la alcantarilla se calculó primero el caudal racional usando C=0.332, obtenido mediante estadísticas zonales del raster ESA WorldCover 2021 v200. Para T=25 años y Kirpich resultó Qp=3.56 m³/s. Se adoptó una alcantarilla de 1.50 m, con capacidad Manning de 7.08 m³/s y factor de seguridad 1.99. El Monte Carlo corregido usa 5000 iteraciones y 200 réplicas bootstrap GEV: la probabilidad anual efectiva es 0.9482 % y el riesgo acumulado en 30 años es 24.86 %. La fracción de indicadores directos (9.56 %) es solo diagnóstica y no sustituye la probabilidad integrada de la CDF GEV.'),P('Para el tanque se probaron hietogramas de 30, 60 y 90 minutos, desplazando el pico al inicio, centro y final. El escenario más exigente requiere 1014.75 m³ y alcanza 1.92 m. El tanque propuesto, de 24 × 22 m, ofrece 1056 m³ útiles, 2.0 m de profundidad útil y 0.5 m de borde libre. El margen disponible es 41.25 m³.'),I(BASE/'control_2_1'/'mapa_revision_visual_detalle.png',13.5*cm,9.3*cm)]
story += [P('2.5 Bonificación POT','H2'),P('Como análisis adicional se aplicó Peaks Over Threshold. Se acumularon los datos de 10 minutos a una hora, se eligió el percentil 95 como umbral (0.530 mm/h) y se separaron los eventos por 24 horas para no contar dos veces la misma tormenta. Se obtuvieron 1523 picos independientes y se ajustó una Generalizada de Pareto. Para T=100 años el resultado POT-P95 es 56.35 mm; al cambiar el umbral entre P90 y P98 el resultado varía entre 52.87 y 61.10 mm. La GEV-MLE entrega 93.36 mm, por lo que POT se conserva como sensibilidad y no reemplaza la IDF principal.'),tbl([['T','POT-P90','POT-P95','POT-P98','GEV-MLE'],['2','18.02','18.08','18.29','18.45'],['10','29.04','29.76','30.88','38.81'],['25','37.18','38.67','40.79','55.55'],['100','52.87','56.35','61.10','93.36']])]
story += [P('Discusión y conclusiones','H1'),P('El resultado final no debe leerse como un único número aislado. La lluvia de diseño depende de la GEV-MLE, el caudal depende además de C y del tiempo de concentración, y la respuesta de las obras depende de Manning, la pendiente y el tránsito en el tanque. La mayor incertidumbre está en los retornos largos y en que el outlet es sintético. Con los supuestos actuales, la alternativa calculada es una alcantarilla de 1.50 m y un tanque de 1056 m³, pero el riesgo de 0 % a 30 años debe discutirse y, si el criterio del proyecto lo exige, reducirse con una obra mayor o un alivio de emergencia.'),P('Reproducibilidad y uso de IA','H2'),P('Los datos y scripts están en datos/punto2 y codigo/punto2. La IA ayudó a organizar el código, revisar consistencia y redactar borradores; el grupo debe revisar la versión final y asumir la responsabilidad académica.')]
story += [P('Referencias','H2'),P('Chow, V. T., Maidment, D. R., & Mays, L. W. (1988). Applied hydrology. McGraw-Hill.'),P('Deutscher Wetterdienst. (2026). Datos historicos de precipitacion de la estacion 00020.'),P('European Space Agency. (2021). ESA WorldCover 10 m 2021.') ]

# Anexo visible: tablas y evidencias exigidas explícitamente por la rúbrica de 2.2.
q22 = pd.read_csv(BASE/'extremos_2_2'/'quantiles_3methods.csv')
b22 = pd.read_csv(BASE/'extremos_2_2'/'bootstrap_ci_gev.csv')
q10 = q22[q22.duration=='10min'].drop_duplicates(['distribution','method'])
qtable = [['Distribución-método','T=2','T=5','T=10','T=25','T=50','T=100']]
for _, row in q10.iterrows():
    z = q22[(q22.duration=='10min')&(q22.distribution==row.distribution)&(q22.method==row.method)].set_index('T_years')
    qtable.append([f"{row.distribution}-{row.method}"] + [f"{float(z.loc[T,'quantile_mm']):.2f}" for T in [2,5,10,25,50,100]])
b10 = b22[b22.duration=='10min']
btable = [['T','P2.5','Mediana','P97.5','Ancho relativo']]
for _, row in b10.iterrows():
    btable.append([str(int(row.T_years)),f'{row.q025:.2f}',f'{row["median"]:.2f}',f'{row.q975:.2f}',f'{(row.q975-row.q025)/row["median"]:.2f}'])
story += [PageBreak(), P('Anexo estadístico del apartado 2.2','H1'), P('La siguiente tabla muestra, para la duración de 10 minutos, los seis periodos de retorno solicitados para Gumbel, GEV y Log-Pearson III ajustados por momentos (mom), L-momentos (lmom) y máxima verosimilitud (mle). La tabla completa para todas las duraciones se conserva en quantiles_3methods.csv.','Body'), tbl(qtable), Spacer(1,.25*cm), P('Intervalos bootstrap GEV-MLE para 10 minutos','H2'), tbl(btable), Spacer(1,.25*cm), I(BASE/'extremos_2_2'/'diagrama_lmomentos_2_2.png',11.8*cm,8.8*cm), P('El diagrama de razones de L-momentos se interpreta conjuntamente con KS, Cramér–von Mises, gráficos de probabilidad y estabilidad de cuantiles. La GEV-MLE se seleccionó porque presentó el mejor compromiso de ajuste y flexibilidad de cola; los intervalos bootstrap muestran que los retornos altos son inciertos y no deben presentarse como cifras exactas.','Body')]
idfmet = pd.read_csv(BASE/'idf_2_3'/'idf_fit_error_metrics.csv')
ev = pd.read_csv(BASE/'idf_2_3'/'recent_event_return_period_uncertainty.csv').iloc[0]
itable = [['T','a','eta','RMSE','MAE','R2 log-log']]
for _, rr in idfmet.iterrows(): itable.append([str(int(rr.T_years)),f'{rr.a:.3f}',f'{rr.eta:.3f}',f'{rr.rmse_mm_h:.2f}',f'{rr.mae_mm_h:.2f}',f'{rr.r2_loglog:.3f}'])
event_hi = '>1e6' if ev.T_q975 > 1e6 else f'{ev.T_q975:.2f}'
story += [PageBreak(), P('Fase 4: IDF, KOSTRA y evento reciente','H1'), P('La ley analítica utilizada es i(d,T)=a(T)d^-eta(T), válida entre 0.1667 y 24 horas. La tabla reporta parámetros y errores por periodo de retorno.','Body'), tbl(itable), P(f'El máximo horario de 2021 fue {ev.depth_mm:.2f} mm. Su periodo puntual GEV es {ev.point_estimate_T_years:.2f} años; el bootstrap de {int(ev.bootstrap_replicas)} réplicas da mediana {ev.T_median:.2f} años e intervalo P2.5–P97.5 de {ev.T_q025:.2f}–{event_hi} años. La cola superior inestable refleja que una muestra de 20 años no identifica bien retornos extremos. Se distingue entre evento extremo y anomalía estadística; una tendencia requiere evidencia temporal sistemática.','Body'), P('KOSTRA-DWD-2020 se consultó en el portal oficial del DWD (DOI 10.5676/DWD/KOSTRA-DWD-2020). La comparación local/KOSTRA mezcla escala puntual-areal, periodos de referencia y ajuste estadístico; no se interpreta como sesgo puro.','Body')]
scale = pd.read_csv(BASE/'diseno_2_4'/'escala_metodo_racional.csv')
tanks = pd.read_csv(BASE/'diseno_2_4'/'tanque_escenarios.csv')
stable = [['Escala','Área km²','tc Kirpich (min)','FRA','Q ilustrativo (m³/s)']]
for _,rr in scale.iterrows(): stable.append([str(rr['scale']),f'{rr.area_km2:.3f}',f'{rr.tc_kirchich_min:.1f}',f'{rr.FRA_illustrative:.2f}',f'{rr.rational_Q_with_FRA_m3s:.1f}'])
tcrit = tanks.loc[tanks.max_storage_m3.idxmax()]
story += [PageBreak(), P('Fase 5: diseño hidráulico y sensibilidad','H1'), P('El método racional se considera válido para la microcuenca de 0.123154 km². La tabla de escala muestra por qué no se extrapola a 10, 100 o 2363 km²: aumentan el tiempo de concentración y la heterogeneidad espacial, mientras el FRA pasa a dominar el resultado. Esos caudales grandes son demostrativos, no diseños.','Body'), tbl(stable), I(BASE/'diseno_2_4'/'esquema_alcantarilla_2_4a.png',13.5*cm,5.0*cm), P('El tanque se transitó con piscina nivelada: S(h)=528h y O(h)=Cd Ao sqrt(2gh), Cd=0.65, orificio de 0.30 m y pasos de 10 minutos. El caso crítico fue duración de 60 min, pico final: %.2f m³ y %.2f m de profundidad, con margen de 41.25 m³.'%(tcrit.max_storage_m3,tcrit.max_depth_m), 'Body'), I(BASE/'diseno_2_4'/'esquema_tanque_2_4b.png',13.5*cm,6.7*cm), P('La sensibilidad varía C ±20 %, Manning n, pendiente construida y las tres fórmulas de tc. El diámetro comercial queda entre 0.95 y 1.45 m en las combinaciones evaluadas; la recomendación de 1.50 m conserva margen frente a redondeo y supuestos del outlet sintético.','Body')]
story += [PageBreak(), P('Referencias y transparencia','H1'), P('Las referencias completas en APA 7, con DOI o URL verificable, se conservan en el archivo referencias_apa7.md. La declaración de IA del informe identifica herramientas, tareas, verificaciones, correcciones y contribuciones individuales, conforme al enunciado.','Body'), P('El grupo debe leer las fuentes citadas y poder explicar cualquier figura, tabla, decisión metodológica y limitación durante la presentación oral. La IA se utilizó como apoyo técnico y editorial, no como sustituto de la comprensión ni de la responsabilidad académica.','Body')]
doc=SimpleDocTemplate(str(PDF),pagesize=A4,rightMargin=2.15*cm,leftMargin=2.15*cm,topMargin=1.8*cm,bottomMargin=1.8*cm,title='Informe Tarea 2')
doc.build(story,onFirstPage=footer,onLaterPages=footer)
print(PDF)
